// ==/UserScript==

(() => {
  'use strict';
  const TEMPLATE = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><title>__TITLE__ \u2013 Gantt</title>\n<style>\n.viz-root{\n  --surface-1:#fcfcfb;--text-primary:#0b0b0b;--text-secondary:#52514e;--text-muted:#7a7974;\n  --grid:#e1e0d9;--axis:#c3c2b7;--ring:rgba(11,11,11,.10);--hover:rgba(11,11,11,.04);\n  --good:#0ca30c;--warning:#fab219;--serious:#ec835a;--critical:#d03b3b;--running:#2a78d6;--neutral:#a3a29b;\n}\n@media (prefers-color-scheme: dark){.viz-root{color-scheme:dark;\n  --surface-1:#1a1a19;--text-primary:#f0efec;--text-secondary:#c3c2b7;--text-muted:#8f8e88;\n  --grid:#2c2c2a;--axis:#383835;--ring:rgba(255,255,255,.10);--hover:rgba(255,255,255,.05);--running:#3987e5;--neutral:#6b6a65;}}\nbody{margin:0;font:13px/1.4 system-ui,-apple-system,sans-serif}\n.viz-root{background:var(--surface-1);color:var(--text-primary);min-height:100vh;padding:16px 20px;box-sizing:border-box}\nh1{font-size:16px;margin:0 0 2px}\n.sub{color:var(--text-secondary);margin-bottom:12px}\n.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:10px;color:var(--text-secondary)}\n.controls select,.controls input[type=search]{font:inherit;padding:2px 6px}\n.legend{display:flex;gap:14px;color:var(--text-secondary)}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}\nsvg text{font:12px system-ui,-apple-system,sans-serif;font-variant-numeric:tabular-nums}\n.row:hover .bg{fill:var(--hover)}\n.row{cursor:pointer}\n.dim{opacity:.25}\n.dep .bg{fill:var(--hover)}\n.dep .lbl{font-weight:600}\n#tip{position:fixed;pointer-events:none;background:var(--surface-1);color:var(--text-primary);border:1px solid var(--ring);\n  box-shadow:0 4px 16px rgba(0,0,0,.15);border-radius:6px;padding:8px 10px;max-width:420px;display:none;z-index:10}\n#tip table{border-collapse:collapse;margin-top:4px}#tip td{padding:0 8px 0 0;color:var(--text-secondary);font-variant-numeric:tabular-nums}\n#tip .h{font-weight:600}\n#live:empty{display:none}\n.arr{stroke:var(--axis);fill:none;pointer-events:none}.arr.hl{stroke:var(--text-primary);stroke-width:1.5}\n.viz-root{--hatch-bg:rgba(11,11,11,.03)}@media (prefers-color-scheme: dark){.viz-root{--hatch-bg:rgba(255,255,255,.04)}}\ndetails{margin-top:16px}table.data{border-collapse:collapse}table.data td,table.data th{padding:2px 10px;text-align:left;border-bottom:1px solid var(--grid);font-variant-numeric:tabular-nums}\n</style></head>\n<body><div class=\"viz-root\">\n<h1 id=\"title\"></h1><div class=\"sub\" id=\"sub\"></div><div class=\"sub\" id=\"live\"></div>\n<div class=\"controls\">\n  <label>Sort <select id=\"sort\"><option value=\"start\">Start time</option><option value=\"topo\">Dependency order</option><option value=\"duration\">Duration</option><option value=\"name\">Name</option></select></label>\n  <label><input type=\"checkbox\" id=\"skipped\" checked> Show skipped</label>\n  <label><input type=\"checkbox\" id=\"crit\"> Highlight critical path</label>\n  <label><input type=\"checkbox\" id=\"steps\" checked> Step boundaries</label>\n  <label><input type=\"checkbox\" id=\"arrows\" checked> Dependency arrows</label>\n  <label title=\"Fold succeeded and skipped jobs into one row; failed jobs stay visible\"><input type=\"checkbox\" id=\"collapse-done\"> Collapse finished</label>\n  <input type=\"search\" id=\"filter\" placeholder=\"Filter jobs\u2026\">\n  <span class=\"legend\" id=\"legend\"></span>\n</div>\n<div id=\"chart\"></div>\n<details><summary>Table view</summary><table class=\"data\" id=\"table\"></table></details>\n<div id=\"tip\"></div>\n</div>\n<script>\n// {doc: raw API document, meta: {attempt, logs, title, generated}, live?: {interval, source: 'server' | 'parent'}}\nconst BOOT = __DATA__;\nlet DATA = null;\nconst STATUS = {\n  SUCCEEDED:{c:'--good',icon:'\u2713',label:'Succeeded'}, FAILED:{c:'--critical',icon:'\u2715',label:'Failed'},\n  ERROR:{c:'--critical',icon:'\u2715',label:'Error'}, CANCELLED:{c:'--serious',icon:'\u25a0',label:'Cancelled'},\n  ABORTED:{c:'--serious',icon:'\u25a0',label:'Aborted'}, TIMED_OUT:{c:'--serious',icon:'\u23f1',label:'Timed out'},\n  RUNNING:{c:'--running',icon:'\u25cf',label:'Running'}, IN_PROGRESS:{c:'--running',icon:'\u25cf',label:'Running'},\n  STARTED:{c:'--running',icon:'\u25cf',label:'Running'}, ERRORED:{c:'--neutral',icon:'\u2298',label:'Errored (not run)'},\n  PENDING_APPROVAL:{c:'--warning',icon:'\u23f8',label:'Pending approval'}, WAITING:{c:'--warning',icon:'\u23f8',label:'Waiting'},\n  SKIPPED:{c:'--neutral',icon:'\u2298',label:'Skipped'},\n  QUEUED:{c:'--neutral',icon:'\u25cb',label:'Queued'}, PENDING:{c:'--neutral',icon:'\u25cb',label:'Pending'},\n  UNKNOWN:{c:'--neutral',icon:'\u25cb',label:'Not started'}, STATUS_UNKNOWN:{c:'--neutral',icon:'\u25cb',label:'Not started'},\n};\nconst st = s => STATUS[s] || {c:'--neutral',icon:'?',label:s};\nconst ts = s => s ? new Date(s).getTime() : null;\n// ERRORED is what steps that did not run report in some jobs (where others say SKIPPED); the job can still succeed.\nconst DONE = ['SUCCEEDED','FAILED','ERROR','ERRORED','ABORTED','CANCELLED','TIMED_OUT','SKIPPED'];\nconst fmt = ms => { if (ms == null) return '\u2013'; const s = Math.round(ms/1000); const h = Math.floor(s/3600), m = Math.floor(s%3600/60), r = s%60;\n  return h ? `${h}h${String(m).padStart(2,'0')}m` : m ? `${m}m${String(r).padStart(2,'0')}s` : `${r}s`; };\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n\n// Turn any supported payload into {jobs, run, done, ...}: the REST GetAutomationRun response,\n// or the {\"items\": [...]} output of the Unify MCP automation_jobs_list tool.\nfunction normalize(doc, meta) {\n  let raw = [], run = {};\n  if (doc.items) raw = doc.items;\n  else {\n    const attempts = doc.runAttempts || doc.run_attempts || [];\n    const pick = attempts.find(a => String((a.run || {}).runAttempt ?? '') === String(meta.attempt)) || attempts[0];\n    if (pick) { raw = pick.jobs || []; run = pick.run || {}; } else { raw = doc.jobs || []; run = doc.run || {}; }\n  }\n  // Steps are either {step: {...}} or composite {action: {name, steps: [...]}}; flatten actions into \"Action \u203a step\".\n  const steps = (entries, prefix = '') => (entries || []).flatMap(e => {\n    if (e.action) return steps(e.action.steps, `${prefix}${e.action.name || e.action.id} \u203a `);\n    const s = e.step || e;\n    return s.startedAt || s.started_at || s.name ? [{id: s.id || '', name: prefix + (s.name || s.id || '?'), status: s.status || '',\n      start: s.startedAt || s.started_at || null, end: s.updatedAt || s.updated_at || null}] : [];\n  });\n  const flat = (list, depth = 0, parent = null) => (list || []).flatMap(j => [{\n    id: j.id || j.name, name: j.name || j.id, status: j.status || 'UNKNOWN', message: j.statusMessage || j.status_message || '',\n    start: j.startedAt || j.started_at || null, end: j.updatedAt || j.updated_at || null,\n    deps: j.dependencies || [], depth, parent, steps: steps(j.steps),\n  }, ...flat(j.childJobs || j.child_jobs, depth + 1, j.id)]);\n  const jobs = flat(raw);\n  return {jobs, run, logs: meta.logs, title: run.workflowName || run.name || meta.title, generated: meta.generated, live: BOOT.live};\n}\n\n// Derived state, recomputed by load() on every refresh.\nlet NOW, jobs, byId, kids, t0, t1, critical, level;\nconst collapsed = new Set();\nfunction load(data) {\n  DATA = data;\n  if (!DATA.jobs.length) { document.getElementById('sub').textContent = 'No jobs found in this run (yet).'; jobs = []; return; }\n  jobs = DATA.jobs.map(j => {\n    const s = ts(j.start);\n    // The job record can lag behind its steps: its updatedAt may not move while it runs, and its status may stay\n    // STARTED after its finalize step is done. Trust the steps in both cases.\n    let status = j.status, note = '', end = Math.max(ts(j.end) || 0, ...j.steps.map(x => ts(x.end) || ts(x.start) || 0)) || null;\n    const fin = j.steps.find(x => x.id === 'finalize');\n    if (s && !DONE.includes(status) && fin && DONE.includes(fin.status)) {\n      note = `Reported ${status}, but all its steps have finished`;\n      status = j.steps.some(x => ['FAILED', 'ERROR'].includes(x.status)) ? 'FAILED' : 'SUCCEEDED';\n    }\n    return {...j, status, note, s, end, running: !!s && !DONE.includes(status)};\n  });\n  DATA.done = DONE.includes(DATA.run.status) || jobs.every(j => DONE.includes(j.status));\n  // Static pages freeze running bars at generation time; live pages extend them to the current time.\n  NOW = DATA.live && !DATA.done ? Date.now() : new Date(DATA.generated).getTime();\n  jobs.forEach(j => {\n    j.e = j.running ? Math.max(NOW, j.end || 0) : j.s || DONE.includes(j.status) ? j.end : null;\n    j.dur = j.s && j.e ? j.e - j.s : null;\n    // Steps with distinct start and end times are used as is. Older records only carry a completion time:\n    // such a step runs from the previous step's completion (or the job start) to its own.\n    let prev = j.s;\n    j.steps = j.steps.map(x => {\n      const a = ts(x.start), b = ts(x.end) || a;\n      const step = {...x, s: a && b && b > a ? a : prev, e: b};\n      step.dur = step.s && step.e ? Math.max(0, step.e - step.s) : null;\n      if (b) prev = b;\n      return step;\n    });\n  });\n  byId = Object.fromEntries(jobs.map(j => [j.id, j]));\n  // A reusable workflow call (\"Finalize call X\") is a group: it spans its child jobs and takes its status from them.\n  kids = {};\n  jobs.forEach(j => { if (j.parent != null && byId[j.parent]) (kids[j.parent] = kids[j.parent] || []).push(j); });\n  [...jobs].sort((a, b) => b.depth - a.depth).forEach(j => {\n    const c = kids[j.id];\n    if (!c) return;\n    // The call's own finalize job runs after its children, so include its times too.\n    const ss = [j.s, ...c.map(k => k.s)].filter(Boolean), ee = [j.s ? j.e : null, ...c.map(k => k.e)].filter(Boolean);\n    const started = c.filter(k => k.s || DONE.includes(k.status)), finished = c.filter(k => DONE.includes(k.status));\n    j.group = true;\n    j.name = j.name.replace(/^Finalize call /, '');\n    j.s = ss.length ? Math.min(...ss) : null;\n    j.e = ee.length ? Math.max(...ee) : null;\n    j.dur = j.s && j.e ? j.e - j.s : null;\n    j.status = c.some(k => ['FAILED', 'ERROR'].includes(k.status)) ? 'FAILED'\n      : finished.length === c.length ? (c.every(k => k.status === 'SKIPPED') ? 'SKIPPED' : 'SUCCEEDED')\n      : started.length ? 'RUNNING' : 'UNKNOWN';\n    j.steps = [];\n  });\n  // Waiting: a job is blocked until its last dependency finishes (the \"gate\"), then queued until a runner picks it up.\n  jobs.forEach(j => {\n    if (j.group) { j.pendingDeps = []; j.gate = j.readyAt = j.queued = j.waiting = null; return; }\n    const dd = j.deps.map(d => byId[d]).filter(Boolean);\n    j.pendingDeps = dd.filter(d => !DONE.includes(d.status));\n    const ended = dd.filter(d => DONE.includes(d.status) && d.e);\n    j.gate = !j.pendingDeps.length && ended.length ? ended.reduce((a, b) => b.e > a.e ? b : a) : null;\n    j.readyAt = j.gate ? j.gate.e : null;\n    j.queued = j.s && j.readyAt ? Math.max(0, j.s - j.readyAt) : null;\n    j.waiting = !j.s && !DONE.includes(j.status) ? (j.pendingDeps.length ? 'blocked' : 'ready') : null;\n  });\n  t0 = Math.min(...jobs.map(j => j.s ?? j.e).filter(x => x));\n  t1 = Math.max(...jobs.map(j => j.e).filter(x => x), DATA.live && !DATA.done ? NOW : 0);\n\n  // Critical path: walk back from the last-finishing job through the latest-finishing dependency.\n  critical = new Set();\n  { let cur = jobs.filter(j => j.s).sort((a,b) => b.e - a.e)[0];\n    while (cur && !critical.has(cur.id)) { critical.add(cur.id);\n      cur = cur.deps.map(d => byId[d]).filter(d => d && d.s && d.e).sort((a,b) => b.e - a.e)[0]; } }\n\n  // Dependency depth for topological sort.\n  level = {};\n  const lvl = (j, seen = new Set()) => { if (level[j.id] != null) return level[j.id]; if (seen.has(j.id)) return 0; seen.add(j.id);\n    return level[j.id] = Math.max(-1, ...j.deps.map(d => byId[d] ? lvl(byId[d], seen) : -1)) + 1; };\n  jobs.forEach(j => lvl(j));\n\n  document.getElementById('title').textContent = DATA.title;\n  const counts = {}; jobs.forEach(j => counts[j.status] = (counts[j.status]||0) + 1);\n  document.getElementById('sub').textContent = `${jobs.length} jobs \u00b7 ${DATA.done || !DATA.live ? 'wall clock' : 'elapsed'} ${fmt(t1 - t0)} \u00b7 ` +\n    Object.entries(counts).map(([k,v]) => `${v} ${st(k).label.toLowerCase()}`).join(', ') +\n    ` \u00b7 critical path ${[...critical].length} jobs` +\n    (() => { const q = jobs.map(j => j.queued).filter(v => v != null).sort((a, b) => a - b);\n      return q.length ? ` \u00b7 runner queue median ${fmt(q[Math.floor(q.length / 2)])}, max ${fmt(q[q.length - 1])}` : ''; })() +\n    (() => { const b = jobs.filter(j => j.waiting === 'blocked').length, r = jobs.filter(j => j.waiting === 'ready').length;\n      return (b ? ` \u00b7 ${b} blocked on dependencies` : '') + (r ? ` \u00b7 ${r} waiting for a runner` : ''); })();\n  document.getElementById('legend').innerHTML = [...new Set(jobs.map(j => j.status))].map(s =>\n    `<span><i style=\"background:var(${st(s).c})\"></i>${st(s).icon} ${st(s).label}</span>`).join('') +\n    `<span><svg width=\"22\" height=\"10\"><path d=\"M0 2H6V8H19\" class=\"arr\"/><path d=\"M16 5L22 8L16 11z\" fill=\"var(--axis)\"/></svg> blocked by</span>` +\n    `<span><svg width=\"18\" height=\"10\"><rect width=\"18\" height=\"10\" fill=\"url(#hatch)\" stroke=\"var(--axis)\" stroke-width=\".5\"/></svg> queued for a runner</span>`;\n}\n\nconst tip = document.getElementById('tip');\nfunction stepTable(steps) {\n  if (!steps.length) return '';\n  const top = new Set([...steps].filter(x => x.dur >= 1000).sort((a,b) => b.dur - a.dur).slice(0, 8));\n  const shown = steps.filter(x => top.has(x)), hidden = steps.length - shown.length;\n  const short = n => n.split(' \u203a ').pop();\n  return '<div style=\"margin-top:6px\" class=\"h\">Longest steps</div><table>' + shown.map(x =>\n    `<tr><td>${st(x.status).icon}</td><td title=\"${esc(x.name)}\">${esc(short(x.name))}</td><td>${fmt(x.dur)}</td></tr>`).join('') +\n    (hidden ? `<tr><td></td><td colspan=2>+ ${hidden} more step${hidden > 1 ? 's' : ''}</td></tr>` : '') + '</table>';\n}\nfunction showTip(ev, j) {\n  if (j.synthetic) {\n    tip.innerHTML = `<div class=\"h\">\u2713 ${esc(j.name)}</div><div>${esc(j.detail)}</div>\n      <table><tr><td>Span</td><td>+${fmt(j.s ? j.s - t0 : null)} \u2192 +${fmt(j.e ? j.e - t0 : null)}</td></tr></table>\n      <div style=\"margin-top:4px;color:var(--text-secondary)\">Click to show them</div>`;\n    tip.style.display = 'block';\n    const r = tip.getBoundingClientRect();\n    tip.style.left = Math.min(ev.clientX + 14, innerWidth - r.width - 8) + 'px';\n    tip.style.top = Math.min(ev.clientY + 14, innerHeight - r.height - 8) + 'px';\n    return;\n  }\n  const waitRows = j.gate ? `<tr><td>Blocked by</td><td>${esc(j.gate.name)} (until +${fmt(j.readyAt - t0)})</td></tr>` +\n      (j.queued != null ? `<tr><td>Queued for runner</td><td>${fmt(j.queued)}</td></tr>` : '') +\n      (j.waiting === 'ready' ? `<tr><td>Waiting for runner</td><td>${fmt(NOW - j.readyAt)}</td></tr>` : '')\n    : j.waiting === 'blocked' ? `<tr><td>Waiting on</td><td>${j.pendingDeps.map(d => `${st(d.status).icon} ${esc(d.name)}`).join('<br>')}</td></tr>` : '';\n  tip.innerHTML = `<div class=\"h\">${st(j.status).icon} ${esc(j.name)}</div>\n    <div>${st(j.status).label}${j.message ? ' \u2014 ' + esc(j.message) : ''}</div>\n    ${j.note ? `<div style=\"color:var(--text-muted)\">${esc(j.note)}</div>` : ''}\n    <table><tr><td>Starts at</td><td>+${fmt(j.s ? j.s - t0 : null)}</td></tr>\n    <tr><td>Duration</td><td>${fmt(j.dur)}</td></tr>\n    ${waitRows}\n    ${critical.has(j.id) ? '<tr><td colspan=2>On critical path</td></tr>' : ''}</table>\n    ${j.group ? `<div style=\"margin-top:4px;color:var(--text-secondary)\">Workflow call \u00b7 ${kids[j.id].length} jobs \u00b7 click to ${collapsed.has(j.id) ? 'expand' : 'collapse'}</div>`\n      : j.deps.length ? `<div style=\"margin-top:4px;color:var(--text-secondary)\">Needs: ${j.deps.map(esc).join(', ')}</div>` : ''}\n    ${stepTable(j.steps)}`;\n  tip.style.display = 'block';\n  const r = tip.getBoundingClientRect();\n  tip.style.left = Math.min(ev.clientX + 14, innerWidth - r.width - 8) + 'px';\n  tip.style.top = Math.min(ev.clientY + 14, innerHeight - r.height - 8) + 'px';\n}\n\nconst DEFS = `<defs>\n  <pattern id=\"hatch\" width=\"5\" height=\"5\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n    <rect width=\"5\" height=\"5\" fill=\"var(--hatch-bg)\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"5\" stroke=\"var(--axis)\" stroke-width=\"1.5\"/></pattern>\n  <marker id=\"ah\" viewBox=\"0 0 6 6\" refX=\"5\" refY=\"3\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0L6 3L0 6z\" fill=\"var(--axis)\"/></marker>\n  <marker id=\"ahh\" viewBox=\"0 0 6 6\" refX=\"5\" refY=\"3\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0L6 3L0 6z\" fill=\"var(--text-primary)\"/></marker>\n</defs>`;\n// Highlight dependency rows and arrows touching the hovered job.\nfunction highlight(chart, id) {\n  const j = id && byId[id];\n  chart.querySelectorAll('.row').forEach(r => r.classList.toggle('dep',\n    !!j && (j.deps.includes(r.dataset.id) || byId[r.dataset.id].deps.includes(id))));\n  chart.querySelectorAll('.arr').forEach(a => { const on = !!j && (a.dataset.from === id || a.dataset.to === id);\n    a.classList.toggle('hl', on); a.setAttribute('marker-end', on ? 'url(#ahh)' : 'url(#ah)'); if (on) a.parentNode.appendChild(a); });\n}\n\nfunction render() {\n  if (!jobs.length) { document.getElementById('chart').innerHTML = ''; return; }\n  const sort = document.getElementById('sort').value;\n  const q = document.getElementById('filter').value.toLowerCase();\n  const showCrit = document.getElementById('crit').checked, showSteps = document.getElementById('steps').checked;\n  const showArrows = document.getElementById('arrows').checked;\n  const showSkipped = document.getElementById('skipped').checked;\n  const match = j => (showSkipped || j.status !== 'SKIPPED') && j.name.toLowerCase().includes(q);\n  const visible = j => match(j) || (kids[j.id] || []).some(visible);\n  const key = {start: j => j.s ?? j.e ?? Infinity, topo: j => level[j.id] * 1e15 + (j.s ?? j.e ?? 0),\n               duration: j => -(j.dur ?? -1), name: j => j.name}[sort];\n  const cmp = (a, b) => { const x = key(a), y = key(b); return x < y ? -1 : x > y ? 1 : 0; };\n  // Collapse finished: succeeded and skipped jobs (and workflow calls whose jobs are all done) fold into one row.\n  const collapseDone = document.getElementById('collapse-done').checked;\n  const folds = j => collapseDone && ['SUCCEEDED', 'SKIPPED'].includes(j.status);\n  const folded = [];\n  // Sort siblings, keeping each workflow call's jobs right under it.\n  const order = list => list.filter(visible).sort(cmp).flatMap(j => {\n    if (folds(j)) { folded.push(j); return []; }\n    return [j, ...(collapsed.has(j.id) ? [] : order(kids[j.id] || []))];\n  });\n  const rows = order(jobs.filter(j => j.parent == null || !byId[j.parent]));\n  const subtree = j => [j, ...(kids[j.id] || []).flatMap(subtree)];\n  const foldedAll = folded.flatMap(subtree), foldedLeaves = foldedAll.filter(j => !j.group);\n  if (foldedLeaves.length) {\n    const ok = foldedLeaves.filter(j => j.status === 'SUCCEEDED').length, skipped = foldedLeaves.length - ok;\n    const ss = foldedAll.map(j => j.s).filter(Boolean), ee = foldedAll.map(j => j.e).filter(Boolean);\n    const summary = {id: '__finished__', synthetic: true, name: `${foldedLeaves.length} finished jobs`, status: 'SUCCEEDED',\n      detail: [ok && `${ok} succeeded`, skipped && `${skipped} skipped`].filter(Boolean).join(', '),\n      s: ss.length ? Math.min(...ss) : null, e: ee.length ? Math.max(...ee) : null, deps: [], depth: 0, steps: []};\n    summary.dur = summary.s && summary.e ? summary.e - summary.s : null;\n    byId[summary.id] = summary;\n    rows.unshift(summary);\n  }\n\n  // Label column: room for the name plus the \"\u00b7 N jobs\" / \"\u00b7 34 succeeded, 2 skipped\" suffixes.\n  const labelLen = j => j.name.length + j.depth * 2 + (j.group ? 10 : 0) + (j.synthetic ? j.detail.length + 5 : 0);\n  const RH = 22, LW = Math.min(420, 40 + Math.max(...rows.map(labelLen)) * 7), DW = 64, TOP = 26;\n  const W = Math.max(700, document.getElementById('chart').clientWidth), PW = W - LW - DW - 16;\n  const H = TOP + rows.length * RH + 8;\n  const x = t => LW + DW + (t - t0) / (t1 - t0 || 1) * PW;\n\n  // Axis ticks at a \"nice\" interval.\n  const span = (t1 - t0) / 60000, step = [0.5,1,2,5,10,15,30,60,120,240].find(s => span / s <= 10) || 480;\n  let g = '';\n  for (let m = 0; m <= span; m += step) {\n    const X = x(t0 + m * 60000);\n    g += `<line x1=\"${X}\" x2=\"${X}\" y1=\"${TOP-4}\" y2=\"${H}\" stroke=\"var(--grid)\"/>\n          ${DATA.live && !DATA.done && Math.abs(X - x(NOW)) < 40 ? '' :\n            `<text x=\"${X}\" y=\"${TOP-10}\" text-anchor=\"middle\" fill=\"var(--text-muted)\">${m >= 60 ? (m/60)+'h' : m+'m'}</text>`}`;\n  }\n  g += `<line x1=\"${LW+DW}\" x2=\"${LW+DW+PW}\" y1=\"${TOP-4}\" y2=\"${TOP-4}\" stroke=\"var(--axis)\"/>`;\n  if (DATA.live && !DATA.done)\n    g += `<line x1=\"${x(NOW)}\" x2=\"${x(NOW)}\" y1=\"${TOP-4}\" y2=\"${H}\" stroke=\"var(--running)\" stroke-dasharray=\"3 3\"/>\n          <text x=\"${x(NOW)}\" y=\"${TOP-10}\" text-anchor=\"end\" fill=\"var(--running)\">now </text>`;\n  // One arrow per started job, from the end of the dependency that gated it to its start.\n  const rowY = Object.fromEntries(rows.map((j, i) => [j.id, TOP + i * RH + RH / 2]));\n  // Arrows from folded jobs start at the \"finished jobs\" row.\n  foldedAll.forEach(j => { if (rowY[j.id] == null) rowY[j.id] = rowY.__finished__; });\n  if (showArrows) rows.forEach(j => {\n    if (!j.gate || !j.s) return;\n    // A gate inside a collapsed workflow call is drawn from the call's row.\n    let from = j.gate;\n    while (from && rowY[from.id] == null) from = byId[from.parent];\n    if (!from) return;\n    const x0 = x(j.gate.e), x1 = x(j.s), xm = Math.min(x0 + 6, x1 - 3);\n    g += `<path class=\"arr\" data-from=\"${esc(from.id)}\" data-to=\"${esc(j.id)}\" d=\"M${x0} ${rowY[from.id]}H${xm}V${rowY[j.id]}H${x1 - 1}\" marker-end=\"url(#ah)\"/>`;\n  });\n\n  rows.forEach((j, i) => {\n    const y = TOP + i * RH, cy = y + RH/2, col = `var(${st(j.status).c})`;\n    const dim = showCrit && !critical.has(j.id) ? ' dim' : '';\n    let bar = '';\n    if ((j.group || j.synthetic) && j.s && j.e) {\n      // Bracket spanning the called workflow's jobs (or the folded finished jobs).\n      const x0 = x(j.s), x1 = Math.max(x0 + 3, x(j.e));\n      bar += `<rect x=\"${x0}\" y=\"${cy-2}\" width=\"${x1 - x0}\" height=\"4\" rx=\"1\" fill=\"${col}\"/>\n              <rect x=\"${x0}\" y=\"${y+5}\" width=\"2\" height=\"${RH-10}\" fill=\"${col}\"/><rect x=\"${x1-2}\" y=\"${y+5}\" width=\"2\" height=\"${RH-10}\" fill=\"${col}\"/>`;\n    } else if (j.s && j.e) {\n      if (j.queued > 1000)\n        bar += `<rect x=\"${x(j.readyAt)}\" y=\"${y+6}\" width=\"${x(j.s) - x(j.readyAt)}\" height=\"${RH-12}\" fill=\"url(#hatch)\"/>`;\n      const bw = Math.max(3, x(j.e) - x(j.s));\n      bar += `<rect x=\"${x(j.s)}\" y=\"${y+5}\" width=\"${bw}\" height=\"${RH-10}\" rx=\"4\" fill=\"${col}\"/>`;\n      // Only mark boundaries around steps that take a visible share of the job.\n      if (showSteps) { const big = j.steps.filter(s => s.dur > Math.max(5000, (j.dur || 0) * 0.05));\n        new Set(big.flatMap(s => [s.s, s.e])).forEach(t => { if (t > j.s + 1000 && t < j.e - 1000)\n          bar += `<line x1=\"${x(t)}\" x2=\"${x(t)}\" y1=\"${y+5}\" y2=\"${y+RH-5}\" stroke=\"var(--surface-1)\" stroke-width=\"2\"/>`; }); }\n      if (bw > 44) bar += `<text x=\"${x(j.s)+6}\" y=\"${cy+4}\" fill=\"${['WAITING','PENDING_APPROVAL'].includes(j.status) ? '#0b0b0b' : '#fff'}\">${fmt(j.dur)}</text>`;\n    } else if (j.waiting === 'ready' && j.readyAt) {\n      bar += `<rect x=\"${x(j.readyAt)}\" y=\"${y+6}\" width=\"${Math.max(2, x(NOW) - x(j.readyAt))}\" height=\"${RH-12}\" fill=\"url(#hatch)\" stroke=\"var(--axis)\" stroke-width=\".5\"/>`;\n    } else if (j.waiting === 'blocked') {\n      const p = j.pendingDeps;\n      bar += `<text x=\"${Math.max(LW + DW + 4, x(NOW) - 4)}\" y=\"${cy+4}\" text-anchor=\"${x(NOW) - 4 > LW + DW + 200 ? 'end' : 'start'}\" fill=\"var(--text-muted)\">\u29d7 waiting on ${esc(p[0].name)}${p.length > 1 ? ` +${p.length - 1}` : ''}</text>`;\n    } else if (j.e) {\n      bar += `<text x=\"${x(j.e)}\" y=\"${cy+4}\" text-anchor=\"middle\" fill=\"${col}\">${st(j.status).icon}</text>`;\n    }\n    g += `<g class=\"row${dim}\" data-id=\"${esc(j.id)}\">\n      <rect class=\"bg\" x=\"0\" y=\"${y}\" width=\"${W}\" height=\"${RH}\" fill=\"transparent\"/>\n      <text class=\"lbl\" x=\"${8 + j.depth*14}\" y=\"${cy+4}\" fill=\"var(--text-primary)\">${j.group || j.synthetic ? `<tspan fill=\"var(--text-secondary)\">${j.synthetic || collapsed.has(j.id) ? '\u25b8' : '\u25be'}</tspan> ` : ''}<tspan fill=\"${col}\">${st(j.status).icon}</tspan> ${esc(j.name)}${j.group ? ` <tspan fill=\"var(--text-muted)\">\u00b7 ${kids[j.id].length} jobs</tspan>` : j.synthetic ? ` <tspan fill=\"var(--text-muted)\">\u00b7 ${esc(j.detail)}</tspan>` : ''}</text>\n      <text x=\"${LW+DW-8}\" y=\"${cy+4}\" text-anchor=\"end\" fill=\"var(--text-secondary)\">${fmt(j.dur)}</text>\n      ${bar}</g>`;\n  });\n  const chart = document.getElementById('chart');\n  chart.innerHTML = `<svg width=\"${W}\" height=\"${H}\">${DEFS}${g}</svg>`;\n  chart.querySelectorAll('.row').forEach(el => {\n    const j = byId[el.dataset.id];\n    el.addEventListener('mousemove', ev => { hover = {id: j.id, ev}; showTip(ev, j); });\n    el.addEventListener('mouseenter', () => highlight(chart, j.id));\n    el.addEventListener('mouseleave', () => { hover = null; tip.style.display = 'none'; highlight(chart, null); });\n    if (j.synthetic) el.addEventListener('click', () => setCollapseDone(false));\n    else if (j.group) el.addEventListener('click', () => { collapsed.has(j.id) ? collapsed.delete(j.id) : collapsed.add(j.id); render(); });\n    else if (DATA.logs) el.addEventListener('click', () => {\n      const u = new URL(DATA.logs);\n      u.searchParams.set('job', j.id);\n      const url = u.toString();\n      // Embedded in the Unify UI: open the job's logs in the hosting tab instead of a new one.\n      if (DATA.live && DATA.live.source === 'parent') window.parent.location.href = url; else window.open(url, '_blank');\n    });\n  });\n  if (hover && byId[hover.id]) {\n    showTip(hover.ev, byId[hover.id]);\n    highlight(chart, hover.id);\n  }\n\n  document.getElementById('table').innerHTML = '<tr><th>Job</th><th>Status</th><th>Start</th><th>Duration</th><th>Needs</th></tr>' +\n    rows.map(j => `<tr><td>${esc(j.name)}</td><td>${st(j.status).icon} ${st(j.status).label}</td><td>+${fmt(j.s ? j.s - t0 : null)}</td><td>${fmt(j.dur)}</td><td>${j.deps.map(esc).join(', ')}</td></tr>`).join('');\n}\n['sort','skipped','crit','steps','arrows','filter'].forEach(id => document.getElementById(id).addEventListener('input', render));\n// \"Collapse finished\" is remembered across refreshes and page loads.\nconst collapseBox = document.getElementById('collapse-done');\ntry { collapseBox.checked = localStorage.getItem('unify-gantt-collapse-done') === '1'; } catch (e) { /* storage unavailable */ }\nconst setCollapseDone = on => {\n  collapseBox.checked = on;\n  try { localStorage.setItem('unify-gantt-collapse-done', on ? '1' : '0'); } catch (e) { /* storage unavailable */ }\n  render();\n};\ncollapseBox.addEventListener('input', () => setCollapseDone(collapseBox.checked));\naddEventListener('resize', render);\nlet hover = null;\nload(normalize(BOOT.doc, BOOT.meta));\nrender();\n\n// Live mode: poll the local server while the run is in progress, and tick running bars every second.\nif (DATA.live) {\n  const status = document.getElementById('live');\n  let lastOk = Date.now(), error = null;\n  const showStatus = () => {\n    if (DATA.done) { status.innerHTML = '<b>\u2713 Run finished</b> \u00b7 no longer refreshing'; return; }\n    const ago = Math.round((Date.now() - lastOk) / 1000);\n    status.innerHTML = `<b style=\"color:var(--running)\">\u25cf Live</b> \u00b7 updated ${ago}s ago` +\n      (error ? ` \u00b7 <span style=\"color:var(--critical)\">\u2715 last refresh failed: ${esc(error)}</span>` : '');\n  };\n  // 'server': the local unify-run-gantt --live process; 'parent': the Unify UI page hosting this frame (userscript).\n  const fetchRaw = DATA.live.source === 'parent' ? () => window.parent.unifyGantt.fetchRaw()\n    : async () => { const r = await (await fetch('data', {cache: 'no-store'})).json(); if (r.error && !r.doc) throw new Error(r.error); return r; };\n  const poll = async () => {\n    try {\n      const r = await fetchRaw();\n      error = r.error || null;\n      if (r.doc) { load(normalize(r.doc, r.meta)); lastOk = Date.now(); render(); }\n    } catch (e) { error = e.message || String(e); }\n    showStatus();\n    if (!DATA.done) setTimeout(poll, DATA.live.interval * 1000);\n  };\n  setInterval(() => { if (!DATA.done) { load(DATA); render(); } showStatus(); }, 1000);\n  showStatus();\n  setTimeout(poll, DATA.live.interval * 1000);\n}\n</script></body></html>\n";
  const INTERVAL = 5;
  const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
  // Runs can be nested deeper, e.g. applications/<app>/releases/<release>/runs/...
  // Newer UI URLs drop the organization from the path and pass it as ?organizationId= instead.
  const RUN_RE = new RegExp(`(?:/(${UUID}))?/(?:components|applications)/(${UUID})(?:/[a-z-]+/${UUID})*/runs/(${UUID})/(${UUID})(?:/(\\d+))?`);
  const api = () => (window.__env__ && window.__env__.NX_API_GATEWAY_URL) || 'https://api.cloudbees.io';

  // Reuse the UI's own session: remember the latest bearer token it sends to the API gateway.
  // The token never leaves the page; it is only sent back to the same API host.
  let auth = null;
  const note = (url, value) => {
    if (value && /^Bearer /i.test(value) && String(url).startsWith(api())) auth = value;
  };
  const XHR = window.XMLHttpRequest.prototype, open = XHR.open, setHeader = XHR.setRequestHeader;
  XHR.open = function (method, url) { this.__ganttUrl = url; return open.apply(this, arguments); };
  XHR.setRequestHeader = function (k, v) { if (/^authorization$/i.test(k)) note(this.__ganttUrl, v); return setHeader.apply(this, arguments); };
  const pageFetch = window.fetch;
  window.fetch = function (input, init) {
    try {
      const url = typeof input === 'string' || input instanceof URL ? input : input.url;
      const headers = new Headers((init && init.headers) || (input instanceof Request ? input.headers : undefined));
      note(url, headers.get('authorization'));
    } catch (e) { /* never break the app */ }
    return pageFetch.apply(this, arguments);
  };

  const parseRun = () => {
    const m = location.pathname.match(RUN_RE);
    if (!m) return null;
    const [, pathOrg, component, automation, run, attempt] = m;
    const query = new URLSearchParams(location.search);
    const org = pathOrg || query.get('organizationId');
    if (!org) return null;
    // Logs live under the same page path as the run itself; keep the page's query except the selected job/step.
    query.delete('job');
    query.delete('step');
    const qs = query.toString();
    return {org, component, automation, run, attempt: attempt || '1',
      logs: `${location.origin}${location.pathname.slice(0, m.index + m[0].length)}${attempt ? '' : '/1'}/logs${qs ? '?' + qs : ''}`};
  };

  let current = null;  // run shown in the overlay
  // Called by the Gantt frame on every refresh.
  window.unifyGantt = {
    async fetchRaw() {
      const ref = current;
      if (!ref) throw new Error('overlay closed');
      if (!auth) throw new Error('no API session captured yet \u2014 reload the page');
      const url = `${api()}/v1/organizations/${ref.org}/services/${ref.component}/automations/${ref.automation}/runs/${ref.run}/attempts/${ref.attempt}`;
      const r = await pageFetch.call(window, url, {headers: {Authorization: auth, Accept: 'application/json'}});
      if (!r.ok) throw new Error(`HTTP ${r.status} from ${new URL(url).host}`);
      return {doc: await r.json(), meta: {attempt: ref.attempt, logs: ref.logs, title: `Run ${ref.run} #${ref.attempt}`,
        generated: new Date().toISOString()}};
    },
  };

  const css = `
    #unify-gantt-btn{position:fixed;right:20px;bottom:20px;z-index:2147483000;font:600 13px system-ui,sans-serif;
      padding:8px 14px;border-radius:18px;border:1px solid rgba(11,11,11,.15);background:#2a78d6;color:#fff;cursor:pointer;
      box-shadow:0 4px 14px rgba(0,0,0,.2)}
    #unify-gantt-btn:hover{background:#1f63b6}
    #unify-gantt-ovl{position:fixed;inset:0;z-index:2147483001;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center}
    #unify-gantt-ovl .panel{width:96vw;height:92vh;background:#fcfcfb;border-radius:10px;overflow:hidden;display:flex;flex-direction:column;
      box-shadow:0 10px 40px rgba(0,0,0,.35)}
    #unify-gantt-ovl .bar{display:flex;align-items:center;gap:12px;padding:6px 12px;font:13px system-ui,sans-serif;color:#52514e;
      border-bottom:1px solid #e1e0d9}
    #unify-gantt-ovl .bar b{color:#0b0b0b}#unify-gantt-ovl .bar span{flex:1}
    #unify-gantt-ovl .bar button{font:inherit;border:0;background:none;cursor:pointer;font-size:18px;color:#52514e}
    #unify-gantt-ovl iframe{flex:1;border:0;width:100%}
    #unify-gantt-ovl .msg{padding:24px;font:14px system-ui,sans-serif}
    @media (prefers-color-scheme: dark){#unify-gantt-ovl .panel{background:#1a1a19}#unify-gantt-ovl .bar{color:#c3c2b7;border-color:#2c2c2a}
      #unify-gantt-ovl .bar b{color:#f0efec}#unify-gantt-ovl .bar button{color:#c3c2b7}#unify-gantt-ovl .msg{color:#f0efec}}`;

  function close() {
    document.getElementById('unify-gantt-ovl')?.remove();
    current = null;
  }

  async function openGantt() {
    const ref = parseRun();
    if (!ref) return;
    close();
    current = ref;
    const ovl = document.createElement('div');
    ovl.id = 'unify-gantt-ovl';
    ovl.innerHTML = `<div class="panel"><div class="bar"><b>Gantt</b><span>run ${ref.run} \u00b7 attempt ${ref.attempt}</span>
      <button title="Close (Esc)">\u2715</button></div><div class="msg">Loading\u2026</div></div>`;
    ovl.querySelector('button').onclick = close;
    ovl.addEventListener('click', e => { if (e.target === ovl) close(); });
    document.body.appendChild(ovl);
    try {
      const raw = await window.unifyGantt.fetchRaw();
      if (current !== ref) return;
      const boot = {...raw, live: {interval: INTERVAL, source: 'parent'}};
      const frame = document.createElement('iframe');
      frame.srcdoc = TEMPLATE.replace('__TITLE__', () => `Run ${ref.run}`)
        .replace('__DATA__', () => JSON.stringify(boot).replace(/<\//g, '<\\/'));
      ovl.querySelector('.msg').replaceWith(frame);
      frame.addEventListener('load', () => frame.contentWindow.addEventListener('keydown', e => { if (e.key === 'Escape') close(); }));
    } catch (e) {
      ovl.querySelector('.msg').textContent = `Could not load the run: ${e.message}`;
    }
  }

  // Unify is a single-page app: show the button only while a run page is displayed.
  function sync() {
    if (!document.body) return;
    if (!document.getElementById('unify-gantt-css')) {
      const st = document.createElement('style');
      st.id = 'unify-gantt-css';
      st.textContent = css;
      document.head.appendChild(st);
    }
    let btn = document.getElementById('unify-gantt-btn');
    const onRun = !!parseRun();
    if (onRun && !btn) {
      btn = document.createElement('button');
      btn.id = 'unify-gantt-btn';
      btn.textContent = '\u25a4 Gantt';
      btn.title = 'Show all jobs of this run as a live Gantt chart';
      btn.onclick = openGantt;
      document.body.appendChild(btn);
    } else if (!onRun && btn) {
      btn.remove();
      close();
    }
  }
  document.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
  setInterval(sync, 1000);
  document.addEventListener('DOMContentLoaded', sync);
})();
